package dev.unbox.unpvp;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
/** Local coarse measurements: no addresses, account identifiers, grants or world names. */
public final class JoinDiagnostics {
 private static final Path FILE=SocialBridge.root().resolve("logs/unbox-network.json");
 private static final ExecutorService IO=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"Unbox network report");t.setDaemon(true);return t;});
 private static final List<JsonObject> attempts=new ArrayList<>();private static JsonObject current;
 private static final List<Integer> latency=new ArrayList<>();private static long started,lastSample,lastSave;private static boolean connected;
 static volatile String exportStatus="";
 static void init(){try{if(Files.isRegularFile(FILE)&&Files.size(FILE)<1048576){JsonObject saved=new JsonParser().parse(new String(Files.readAllBytes(FILE),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();for(JsonElement entry:saved.getAsJsonArray("attempts")){if(entry.isJsonObject())attempts.add(entry.getAsJsonObject());}while(attempts.size()>64)attempts.remove(0);}}catch(Exception ignored){}}
 public static void shutdown(){save();IO.shutdown();try{IO.awaitTermination(2,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
 static synchronized void begin(){connected=false;latency.clear();if(current!=null)finish("superseded");current=new JsonObject();current.addProperty("attempt",UUID.randomUUID().toString());current.addProperty("startedAt",System.currentTimeMillis());current.addProperty("minecraft","1.8.9");current.addProperty("loader","forge");current.addProperty("route","pending");current.addProperty("p2pEnabled",true);current.add("stages",new JsonArray());started=System.nanoTime();stage("accepted");}
 static synchronized void stage(String name){if(current==null)return;JsonObject event=new JsonObject();event.addProperty("stage",name);event.addProperty("elapsedMs",(System.nanoTime()-started)/1000000);current.getAsJsonArray("stages").add(event);}
 static synchronized void route(String route){if(current!=null)current.addProperty("route",route);}
 static synchronized void finish(String result){if(current==null)return;stage(result);current.addProperty("outcome",result);current.addProperty("elapsedMs",(System.nanoTime()-started)/1000000);attempts.add(current);if(attempts.size()>64)attempts.remove(0);current=null;if(result.equals("joined")){latency.clear();connected=true;lastSample=0;}save();}
 static synchronized void tick(Minecraft mc){if(!connected)return;if(mc.theWorld==null||mc.getIntegratedServer()!=null||mc.getNetHandler()==null){connected=false;save();return;}long now=System.currentTimeMillis();if(now-lastSample<1000)return;lastSample=now;if(mc.thePlayer!=null){net.minecraft.client.network.NetworkPlayerInfo info=mc.getNetHandler().getPlayerInfo(mc.thePlayer.getUniqueID());if(info!=null&&info.getResponseTime()>0){latency.add(info.getResponseTime());if(latency.size()>600)latency.remove(0);}}if(now-lastSave>10000){lastSave=now;save();}}
 private static int percentile(List<Integer> samples,double p){if(samples.isEmpty())return -1;List<Integer> copy=new ArrayList<>(samples);Collections.sort(copy);return copy.get(Math.max(0,(int)Math.ceil(p*copy.size())-1));}
 static synchronized JsonObject report(){JsonObject report=new JsonObject();report.addProperty("schema",1);report.addProperty("exportedAt",System.currentTimeMillis());report.addProperty("measurement","server_reported_keepalive_ms; repeated 1s observations, not independent packets");report.addProperty("p2pEnabled",true);report.addProperty("latencySamples",latency.size());report.addProperty("latencyMedianMs",percentile(latency,.5));report.addProperty("latencyP95Ms",percentile(latency,.95));report.addProperty("connected",connected);JsonArray all=new JsonArray();attempts.forEach(a->all.add(SocialBridge.copy(a)));if(current!=null)all.add(SocialBridge.copy(current));report.add("attempts",all);return report;}
 static synchronized List<String> lines(){JsonObject v=report();long joined=attempts.stream().filter(a->SocialBridge.text(a,"outcome").equals("joined")).count();JsonObject last=current!=null?current:attempts.isEmpty()?new JsonObject():attempts.get(attempts.size()-1);return Arrays.asList("Route: "+SocialBridge.text(last,"route"),"Joined attempts: "+joined+" / "+attempts.size()+" recorded segments", "Reported latency: "+(latency.isEmpty()?"Waiting for server samples":percentile(latency,.5)+" ms median / "+percentile(latency,.95)+" ms p95"),"Public P2P: VoxLink; relay follows unsuccessful direct attempts.","Latency uses server keepalive estimates, not packet-loss measurements.","Restarts are separate segments; cancellations are not network failures.","Reports are saved to logs/unbox-network.json.");}
 static synchronized void save(){String json=new GsonBuilder().setPrettyPrinting().create().toJson(report());IO.submit(()->{try{Files.createDirectories(FILE.getParent());Path tmp=FILE.resolveSibling(".unbox-network.tmp");Files.write(tmp,json.getBytes(java.nio.charset.StandardCharsets.UTF_8));Files.move(tmp,FILE,StandardCopyOption.REPLACE_EXISTING);exportStatus="Saved: logs/unbox-network.json";}catch(Exception e){exportStatus="Could not save network report. Check available disk space.";}});}
}
